import {createRequire} from 'node:module';
import compat from 'core-js-compat';

const require = createRequire(import.meta.url);
const pkg = require('../package.json');
const coreJsVersion = require('core-js/package.json').version;

/** Not standard, or not needed by tasks. */
const EXCLUDED = new Set(['web.immediate']);

export function generatePolyfillsSource() {
  const {list} = compat({
    targets: pkg.browserslist,
    modules: [/^es\./, /^web\./],
    version: coreJsVersion,
  });
  const modules = list.filter((name) => !EXCLUDED.has(name));
  return [
    '// GENERATED by scripts/generate-polyfills.mjs — do not edit.',
    `// core-js ${coreJsVersion}, browserslist: ${pkg.browserslist.join(', ')}`,
    '//',
    '// Import first in the task entry point:',
    "//   import '@france-ioi/react-task-lib/polyfills';",
    ...modules.map((name) => `import 'core-js/modules/${name}.js';`),
    '',
    'export {};',
    '',
  ].join('\n');
}
